<section class="panel expedicao-panel" data-tab-panel="recebimento" hidden><div class="expedicao-heading"><div><h2>Confirmação de entrega</h2><p>Selecione uma entrega própria e registre a assinatura do destinatário.</p></div></div><div class="expedicao-table-wrap"><table class="data-table expedicao-table entrega-table"><thead><tr><th>Pedido</th><th>Loja</th><th>Romaneio</th><th>Volumes</th><th>Expedido em</th><th>Status</th><th></th></tr></thead><tbody><?php if(!empty($aguardandoRecebimento)):foreach($aguardandoRecebimento as $item):$pedidoEntrega=$item['pedido']??[];$lojaEntrega=trim((string)($pedidoEntrega['cliente_nome_fantasia']??''))?:trim((string)($pedidoEntrega['cliente_razao_social']??''));$dataEntrega=!empty($item['data_expedicao'])?strtotime((string)$item['data_expedicao']):false;?><tr><td><strong><?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?></strong></td><td><span class="entrega-loja"><?= $esc($lojaEntrega?:'Loja não identificada'); ?></span></td><td><?= $esc($item['romaneio']??'—'); ?></td><td><?= (int)($item['volumes']??1); ?></td><td><?php if($dataEntrega):?><span class="expedicao-date"><strong><?= date('Y-m-d',$dataEntrega); ?></strong><small><?= date('H:i:s',$dataEntrega); ?></small></span><?php else:?>—<?php endif;?></td><td><span class="entrega-status">Expedido</span></td><td><button type="button" class="button button-primary" data-entrega-id="<?= (int)$item['id']; ?>" data-entrega-pedido="<?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?>">Entregar</button></td></tr><?php endforeach;else:?><tr><td colspan="7" class="expedicao-empty">Nenhuma entrega própria aguardando confirmação.</td></tr><?php endif;?></tbody></table></div></section>
<div class="entrega-modal" data-entrega-modal hidden><div class="entrega-backdrop" data-entrega-close></div><section class="entrega-dialog"><header><div><h3>Confirmar entrega</h3><p>Pedido <strong data-entrega-label></strong></p></div><button type="button" class="entrega-close" data-entrega-close>×</button></header><form class="entrega-form" data-base-action="<?= $esc($url('expedicao/recebimento')); ?>"><input type="hidden" name="expedicao_id"><label>Nome do recebedor<input type="text" name="recebedor_nome" maxlength="120" required></label><label>Assinatura do recebedor<span class="entrega-pad"><svg data-entrega-svg viewBox="0 0 900 270" preserveAspectRatio="none"></svg><i></i><button type="button" class="button button-outline" data-entrega-clear>Limpar</button></span><input type="hidden" name="assinatura_recebedor"></label><footer><button type="button" class="button button-outline" data-entrega-close>Cancelar</button><button type="submit" class="button button-primary" data-entrega-submit>Confirmar entrega</button></footer></form></section></div>
<style>.entrega-table th,.entrega-table td{text-align:center!important;vertical-align:middle!important}.entrega-table th{font-size:10.6px!important}.entrega-table td{font-size:13px!important;white-space:nowrap}.entrega-table :is(th,td):nth-child(2){width:170px;max-width:170px}.entrega-loja{display:-webkit-box;height:32px;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-height:16px;white-space:normal;overflow-wrap:anywhere}.entrega-status{display:inline-flex;padding:6px 10px;border-radius:999px;background:#e0f2fe;color:#0369a1;font-size:12px;font-weight:850}.entrega-modal{position:fixed;z-index:10020;inset:0;display:grid;place-items:center;padding:16px}.entrega-modal[hidden]{display:none}.entrega-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.68);backdrop-filter:blur(4px)}.entrega-dialog{position:relative;width:min(650px,100%);padding:28px;border-radius:24px;background:#fff;box-shadow:0 28px 80px rgba(15,23,42,.3)}.entrega-dialog header{display:flex;justify-content:space-between;margin-bottom:20px}.entrega-dialog h3{margin:0 0 4px}.entrega-dialog p{margin:0;color:var(--text-muted)}.entrega-close{width:36px;height:36px;border:0;border-radius:11px;background:var(--surface-muted);font-size:24px}.entrega-form{display:grid;gap:17px}.entrega-form label{display:grid;gap:8px;font-weight:800}.entrega-form input[type=text]{min-height:50px;padding:0 14px;border:1px solid var(--border);border-radius:13px;font:inherit}.entrega-pad{position:relative;display:block;height:220px;overflow:hidden;border:1px dashed color-mix(in srgb,var(--primary) 55%,var(--border));border-radius:15px;background:#fff}.entrega-pad.has-ink{border-color:var(--primary)}.entrega-pad svg{position:absolute;z-index:2;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.entrega-pad i{position:absolute;z-index:1;left:9%;right:9%;bottom:28%;height:1px;background:#94a3b8}.entrega-pad button{position:absolute;z-index:3;right:9px;top:9px;min-height:36px!important;padding:6px 11px!important}.entrega-form footer{display:flex;justify-content:flex-end;gap:10px}.entrega-form footer .button{min-height:46px}@media(max-width:600px){.entrega-dialog{padding:20px}.entrega-pad{height:190px}.entrega-form footer{display:grid;grid-template-columns:1fr 1fr}}</style>
<script>(()=>{const modal=document.querySelector('[data-entrega-modal]'),form=modal?.querySelector('.entrega-form'),pad=form?.querySelector('.entrega-pad'),svg=form?.querySelector('[data-entrega-svg]'),hidden=form?.elements.assinatura_recebedor,submit=form?.querySelector('[data-entrega-submit]');if(!modal||!form||!pad||!svg||!hidden||!submit)return;let drawing=false,current=null,ink=false;const point=e=>{const r=svg.getBoundingClientRect();return{x:(e.clientX-r.left)*900/r.width,y:(e.clientY-r.top)*270/r.height}};pad.addEventListener('pointerdown',e=>{if(e.target.closest('[data-entrega-clear]'))return;e.preventDefault();drawing=true;ink=true;const p=point(e);current=document.createElementNS('http://www.w3.org/2000/svg','path');current.setAttribute('d',`M${p.x} ${p.y} l.5 .5`);current.setAttribute('fill','none');current.setAttribute('stroke','#111827');current.setAttribute('stroke-width','4');current.setAttribute('stroke-linecap','round');current.setAttribute('stroke-linejoin','round');svg.appendChild(current);pad.classList.add('has-ink')},true);window.addEventListener('pointermove',e=>{if(!drawing||!current)return;e.preventDefault();const p=point(e);current.setAttribute('d',`${current.getAttribute('d')} L${p.x} ${p.y}`)},true);window.addEventListener('pointerup',()=>{drawing=false;current=null},true);const clear=()=>{svg.replaceChildren();hidden.value='';drawing=false;current=null;ink=false;pad.classList.remove('has-ink')};form.querySelector('[data-entrega-clear]').addEventListener('click',clear);const close=()=>{modal.hidden=true;document.body.style.overflow='';form.reset();clear()};document.querySelectorAll('[data-entrega-close]').forEach(b=>b.addEventListener('click',close));document.querySelectorAll('[data-entrega-id]').forEach(b=>b.addEventListener('click',()=>{clear();form.action=`${form.dataset.baseAction}/${encodeURIComponent(b.dataset.entregaId)}`;form.elements.expedicao_id.value=b.dataset.entregaId;modal.querySelector('[data-entrega-label]').textContent=b.dataset.entregaPedido||'';modal.hidden=false;document.body.style.overflow='hidden';form.elements.recebedor_nome.focus()}));const svgData=()=>{if(!ink||!svg.querySelector('path'))throw new Error('Faça a assinatura do recebedor.');const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','900');clone.setAttribute('height','270');const raw=new XMLSerializer().serializeToString(clone),bytes=new TextEncoder().encode(raw);let binary='';bytes.forEach(byte=>binary+=String.fromCharCode(byte));return`data:image/svg+xml;base64,${btoa(binary)}`};form.addEventListener('submit',async e=>{e.preventDefault();if(form.dataset.saving==='1')return;try{hidden.value=svgData();form.dataset.saving='1';submit.disabled=true;const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível salvar a entrega.');window.showAppToast?.('Assinatura salva com sucesso.','success');setTimeout(()=>location.assign(`${location.pathname}?tab=concluidos`),350)}catch(error){window.showAppToast?.(error.message||'Não foi possível salvar a entrega.','error')}finally{delete form.dataset.saving;submit.disabled=false}},true)})();</script>
